const HEADER_LEN: usize = 14;
fn encode(seed: u64) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(HEADER_LEN);
    bytes.extend_from_slice(b"RSTY");
    bytes.extend_from_slice(&1_u16.to_le_bytes());
    bytes.extend_from_slice(&seed.to_le_bytes());
    bytes
}
fn decode(bytes: &[u8]) -> Result<u64, &'static str> {
    if bytes.len() != HEADER_LEN { return Err("invalid header length"); }
    if &bytes[0..4] != b"RSTY" { return Err("wrong file family"); }
    let version = u16::from_le_bytes([bytes[4],bytes[5]]);
    if version != 1 { return Err("unsupported format version"); }
    let mut seed = [0_u8;8];
    seed.copy_from_slice(&bytes[6..14]);
    Ok(u64::from_le_bytes(seed))
}
fn main() {
    let bytes = encode(42);
    assert_eq!(bytes.len(),14);
    assert_eq!(decode(&bytes),Ok(42));
    for end in 0..14 { assert!(decode(&bytes[..end]).is_err()); }
    println!("header round-trip and truncation checks pass");
}

fn encode(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i=0;
    while i<data.len() {
        let value=data[i]; let mut count=1_usize;
        while i+count<data.len() && data[i+count]==value && count<255 { count+=1; }
        out.extend_from_slice(&[count as u8,value]); i+=count;
    }
    out
}
fn decode(data: &[u8], max: usize) -> Result<Vec<u8>, &'static str> {
    if data.len()%2!=0 { return Err("truncated run"); }
    let mut out=Vec::new();
    for pair in data.chunks_exact(2) {
        let count=pair[0] as usize;
        if count==0 { return Err("empty run"); }
        let end=out.len().checked_add(count).ok_or("length overflow")?;
        if end>max { return Err("output limit"); }
        out.resize(end,pair[1]);
    }
    Ok(out)
}
fn main() {
    let input=vec![7;4096]; let packed=encode(&input);
    assert_eq!(decode(&packed,4096),Ok(input));
    assert!(decode(&packed,4095).is_err());
    assert!(decode(&[1],4096).is_err());
    println!("4096 uniform bytes -> {} bytes",packed.len());
}

#[derive(Clone, Debug, PartialEq)]
struct Particle { x: i32, velocity_x: i32, material: u8 }
#[derive(Clone, Debug, PartialEq)]
struct Snapshot { step: u64, cells: Vec<u8>, particles: Vec<Particle> }
fn main() {
    let mut live=Snapshot { step: 10, cells: vec![0,2,0],
        particles: vec![Particle{x:4,velocity_x:3,material:2}] };
    let captured=live.clone();
    live.step+=1;
    live.cells.swap(1,2);
    live.particles[0].x+=live.particles[0].velocity_x;
    assert_eq!(captured.step,10);
    assert_eq!(captured.cells,vec![0,2,0]);
    assert_eq!(captured.particles[0].x,4);
    assert_eq!(live.particles[0].x,7);
    println!("snapshot retained tick 10; live world advanced");
}

#[derive(Default)]
struct Store { committed: u64, complete: Vec<u64> }
fn recover(store: &Store) -> Option<u64> {
    store.complete.iter().copied().find(|id| *id==store.committed)
}
fn save_model(crash_after: u8) -> Store {
    let mut s=Store {committed:1,complete:vec![1]};
    if crash_after==0 { return s; }
    // All payloads and manifest for generation 2 now validate.
    s.complete.push(2);
    if crash_after==1 { return s; }
    // Publish the commit reference only after completion.
    s.committed=2;
    s
}
fn main() {
    assert_eq!(recover(&save_model(0)),Some(1));
    assert_eq!(recover(&save_model(1)),Some(1));
    assert_eq!(recover(&save_model(2)),Some(2));
    println!("every interruption selects a complete generation");
}

#[derive(Clone, Copy)]
enum Generator { V1, V2 }
fn parse_version(id: u16) -> Result<Generator,&'static str> {
    match id {1=>Ok(Generator::V1),2=>Ok(Generator::V2),_=>Err("unsupported generator")}
}
fn height(version: Generator,x:i32) -> i32 {
    match version {
        Generator::V1 => 20+x.rem_euclid(4),
        Generator::V2 => 40+x.rem_euclid(8),
    }
}
fn main() {
    let world_generator=parse_version(1).unwrap();
    let new_default=Generator::V2;
    assert_eq!(height(world_generator,64),20);
    assert_eq!(height(new_default,64),40);
    assert!(parse_version(99).is_err());
    println!("old world keeps its generator; new worlds may use v2");
}

#[derive(Debug)]
struct Resident { revision:u64, saved_revision:u64, active:bool }
impl Resident {
    fn dirty(&self)->bool {self.revision!=self.saved_revision}
    fn acknowledge(&mut self,written:u64) {
        if written==self.revision {self.saved_revision=written;}
    }
    fn may_evict(&self)->bool {!self.active && !self.dirty()}
}
fn main() {
    let mut c=Resident {revision:4,saved_revision:3,active:false};
    let queued=c.revision;
    c.revision=5;
    c.acknowledge(queued);
    assert!(!c.may_evict());
    c.acknowledge(5);
    assert!(c.may_evict());
    println!("stale acknowledgement cannot discard revision 5");
}

