fn visible_rain(x:i32,y:i32,surface:&[i32])->bool {
    x>=0 && (x as usize)<surface.len() && y>=0 && y<surface[x as usize]
}
fn main() {
    // Columns 2 and 3 have a roof at row 4; others have ground at row 10.
    let surface=[10,10,4,4,10,10];
    assert!(visible_rain(2,3,&surface));
    assert!(!visible_rain(2,4,&surface));
    assert!(!visible_rain(2,8,&surface));
    assert!(visible_rain(4,8,&surface));
    assert!(!visible_rain(-1,0,&surface));
    for (x,y) in [(4,2),(3,4),(2,6),(1,8)] {
        println!("pixel ({x},{y}) visible={}",visible_rain(x,y,&surface));
    }
}

fn material_slot(x:i32,y:i32,left:i32,top:i32)->Option<usize> {
    const SLOT:i32=32;
    const COUNT:i32=10;
    if x<left || y<top || y>=top+SLOT || x>=left+COUNT*SLOT {return None;}
    Some(((x-left)/SLOT) as usize)
}
fn main() {
    assert_eq!(material_slot(100,200,100,200),Some(0));
    assert_eq!(material_slot(132,200,100,200),Some(1));
    assert_eq!(material_slot(420,200,100,200),None);
    assert_eq!(material_slot(100,232,100,200),None);
    let clicked_slot=material_slot(140,210,100,200);
    let paint_world=clicked_slot.is_none();
    assert!(!paint_world);
    println!("UI click selects slot {:?}; world paint={paint_world}",clicked_slot);
}
